const { Agent } = require("@voltagent/core");
const { createVercelTools } = require("@voltagent/vercel-ai");
const { openai } = require("@ai-sdk/openai");
const { generateText } = require("ai");
const { Client } = require("@modelcontextprotocol/sdk/client/index.js");
const { StdioClientTransport } = require("@modelcontextprotocol/sdk/client/stdio.js");

async function createMcpClient(serverPath) {
  const transport = new StdioClientTransport({
    command: "node",
    args: [serverPath],
  });

  const client = new Client(
    {
      name: "mcp-client",
      version: "1.0.0",
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  await client.connect(transport);
  return client;
}

async function runAgent(prompt) {
  // Initialize MCP clients
  const mathClient = await createMcpClient("/home/user/servers/math-server.js");
  const stringClient = await createMcpClient("/home/user/servers/string-server.js");

  // Retrieve tools from both servers
  const mathTools = await mathClient.listTools();
  const stringTools = await stringClient.listTools();

  // Aggregate tools and convert them to VoltAgent format
  // We assume VoltAgent/Vercel-AI integration can handle these tools
  // Note: VoltAgent's Agent expects tools in a specific format.
  // Using createVercelTools if applicable, or mapping them.

  const mcpTools = [...mathTools.tools, ...stringTools.tools].map(tool => ({
    name: tool.name,
    description: tool.description,
    parameters: tool.inputSchema,
    execute: async (args) => {
      const client = mathTools.tools.find(t => t.name === tool.name) ? mathClient : stringClient;
      const result = await client.callTool({
        name: tool.name,
        arguments: args,
      });
      return result.content;
    }
  }));

  // Create VoltAgent Agent
  const agent = new Agent({
    name: "mcp-agent",
    tools: mcpTools,
  });

  // Run the agent using Vercel AI SDK
  const { text } = await generateText({
    model: openai("gpt-4o-mini"),
    tools: createVercelTools(agent),
    prompt: prompt,
  });

  return text;
}

module.exports = { runAgent };

