import { Agent } from "@voltagent/core";
import { createVercelTools } from "@voltagent/vercel-ai";
import { openai } from "@ai-sdk/openai";
import { generateText } from "ai";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";

async function createMcpClient(serverPath) {
  const transport = new StdioClientTransport({
    command: "node",
    args: [serverPath],
  });

  const client = new Client(
    {
      name: "mcp-client",
      version: "1.0.0",
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  await client.connect(transport);
  return client;
}

export async function runAgent(prompt) {
  // Initialize MCP clients
  const mathClient = await createMcpClient("/home/user/servers/math-server.js");
  const stringClient = await createMcpClient("/home/user/servers/string-server.js");

  // Retrieve tools from both servers
  const mathToolsResult = await mathClient.listTools();
  const stringToolsResult = await stringClient.listTools();

  const mathTools = mathToolsResult.tools;
  const stringTools = stringToolsResult.tools;

  // Aggregate tools and convert them to VoltAgent format
  const mcpTools = [...mathTools, ...stringTools].map(tool => ({
    name: tool.name,
    description: tool.description,
    parameters: tool.inputSchema,
    execute: async (args) => {
      const isMathTool = mathTools.some(t => t.name === tool.name);
      const client = isMathTool ? mathClient : stringClient;
      const result = await client.callTool({
        name: tool.name,
        arguments: args,
      });
      // Extract text content from MCP result
      return result.content.map(c => c.text).join("\n");
    }
  }));

  // Create VoltAgent Agent
  const agent = new Agent({
    name: "mcp-agent",
    tools: mcpTools,
  });

  // Run the agent using Vercel AI SDK
  const { text } = await generateText({
    model: openai("gpt-4o-mini"),
    tools: createVercelTools(agent),
    prompt: prompt,
  });

  // Cleanup: Close MCP connections
  // Note: StdioClientTransport doesn't have a close method, but client has.
  // Actually, we should close the transport or the client.
  // client.close() is generally good practice.
  await mathClient.close();
  await stringClient.close();

  return text;
}

